def seed_case_studies(apps, schema_editor):
    CaseStudy = apps.get_model("case_studies", "CaseStudy")
    for c in CASE_STUDIES:
        defaults = {k: v for k, v in c.items() if k != "slug"}
        defaults["date"] = date.fromisoformat(defaults["date"])
        CaseStudy.objects.update_or_create(slug=c["slug"], defaults=defaults)


def unseed_case_studies(apps, schema_editor):
    CaseStudy = apps.get_model("case_studies", "CaseStudy")
    CaseStudy.objects.filter(slug__in=[c["slug"] for c in CASE_STUDIES]).delete()


class Migration(migrations.Migration):

    dependencies = [
        ("case_studies", "0003_alter_casestudy_banner"),
    ]

    operations = [
        migrations.RunPython(seed_case_studies, unseed_case_studies),
    ]
